class Solution {
  public int maximumAmount(int[][] coins) {
    int m = coins.length, n = coins[0].length;
    final int NEG = Integer.MIN_VALUE / 2;
    int[][][] dp = new int[m][n][3]; // dp[i][j][c]: best total with c neutralizations used
    for (int[][] row : dp) for (int[] cell : row) Arrays.fill(cell, NEG);
    for (int i = 0; i < m; i++) {
      for (int j = 0; j < n; j++) {
        for (int c = 0; c < 3; c++) {
          int best;
          if (i == 0 && j == 0) {
            best = 0;
          } else {
            best = NEG;
            if (i > 0) best = Math.max(best, dp[i - 1][j][c]);
            if (j > 0) best = Math.max(best, dp[i][j - 1][c]);
          }
          int v = coins[i][j];
          int value = NEG;
          if (best > NEG) value = best + v; // take the cell as is
          if (v < 0 && c > 0) {
            // neutralize this cell: come from a state with c - 1 used
            int prev = NEG;
            if (i == 0 && j == 0) prev = 0;
            else {
              if (i > 0) prev = Math.max(prev, dp[i - 1][j][c - 1]);
              if (j > 0) prev = Math.max(prev, dp[i][j - 1][c - 1]);
            }
            if (prev > NEG) value = Math.max(value, prev);
          }
          dp[i][j][c] = value;
        }
      }
    }
    return Math.max(dp[m - 1][n - 1][0], Math.max(dp[m - 1][n - 1][1], dp[m - 1][n - 1][2]));
  }
}
